/* The workloads. Everything is generated by code and seeded, so every run and every emulator version sees exactly the
 * same frames, and each frame is scheduled in emulated time: the ARM9 is never left idle in a scene that burns, so no
 * idle skip can flatter it. Banks: A/B textures (or main BG/OBJ in 2D scenes), E texture palettes or main BG, C/D sub
 * screen, or the capture targets. */
#include "scenes.h"
#include "golden.h"
#include "port.h"

void cp15_flush_code(void);

volatile u32 g_wrong; /* kernels or code that returned a wrong answer: the score of the run's test goes to 0 */
static s16 SIN[1024];
static u32 seed_state = 0x13579BDF;

static u32 rnd(void) {
    u32 x = seed_state;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    return seed_state = x;
}

void scenes_boot(void) {
    /* A sine table by rotation: Q12, 1024 steps. Integer only, so the same on every engine. */
    s32 s = 0, c = 1 << 24;
    for (int i = 0; i < 1024; ++i) {
        SIN[i] = (s16)((s + (1 << 11)) >> 12);
        /* 2*pi/1024 in Q24 */
        s32 ds = (s32)(((s64)c * 102944) >> 24), dc = (s32)(((s64)s * 102944) >> 24);
        s += ds - (dc >> 11);
        c -= dc + (ds >> 11);
    }
}

static inline s32 sin_q(u32 a) { return SIN[a & 1023]; }
static inline s32 cos_q(u32 a) { return SIN[(a + 256) & 1023]; }

/* --- CPU --------------------------------------------------------------------------------------------------------- */

static u32 burn_step;
#define BURN_LINE 172 /* a batch can run for many lines: stop in time to meet the next VBlank */

/* One batch, about a scanline of ARM9 time: the kernels in turn, ARM and Thumb, and the hardware math units. */
static void burn_batch(void) {
    const u32 i = burn_step++;
    const int k = (int)(i % KERNELS), s = (int)((i >> 3) & 3);
    const u32 seed = 0x1000193u * (u32)(s + 1);
    const u32 got = i & 64 ? kernel_thumb(k, seed) : kernel_arm(k, seed);
    if (got != GOLDEN[k][s]) ++g_wrong;
    if ((i & 7) == 0) {
        /* 64 / 32 divide: the answer multiplied back must give the numerator. */
        const s64 num = ((s64)(i * 2654435761u) << 12) + 12345;
        const s32 den = (s32)(i * 40503u % 30011u) + 17;
        REG16(0x04000280) = 1;
        *(volatile s64*)0x04000290 = num;
        *(volatile s64*)0x04000298 = den;
        while (REG16(0x04000280) & 0x8000) {
        }
        const s64 q = *(volatile s64*)0x040002A0, r = *(volatile s64*)0x040002A8;
        if (q * den + r != num) ++g_wrong;
        const u64 square = (u64)(i * 2654435761u) << 8;
        REG16(0x040002B0) = 1;
        *(volatile u64*)0x040002B8 = square;
        while (REG16(0x040002B0) & 0x8000) {
        }
        const u64 root = REG32(0x040002B4);
        if (root * root > square || (root + 1) * (root + 1) <= square) ++g_wrong;
    }
}

/* Scenes start in VBlank, so the wait is for the line in the coming picture; past the picture it stops rather than
 * eat the next frame. */
static void burn_until(u32 line) {
    for (int active = 0;;) {
        const u32 v = VCOUNT;
        if (v < 192) active = 1;
        if (active && v >= line) return;
        burn_batch();
    }
}

/* --- Common setup ------------------------------------------------------------------------------------------------ */

static void dma_off(void) {
    for (int n = 0; n < 4; ++n) DMA_CTL(n) = 0;
}

void gfx_reset(void) {
    IME = 0;
    IE = 0;
    IF = ~0u;
    DISPSTAT = 0;
    dma_off();
    DISPCAPCNT = 0;
    DISPCNT_A = 0;
    DISPCNT_B = 0;
    POWCNT1 = 0x820F; /* main engine on the top panel */
    for (int b = 0; b < 10; ++b)
        if (b != WRAMCNT_) VRAMCNT(b) = 0;
    for (int e = 0; e < 2; ++e) {
        for (int n = 0; n < 4; ++n) {
            BG_CNT(e, n) = 0;
            BG_HOFS(e, n) = 0;
            BG_VOFS(e, n) = 0;
        }
        for (int n = 2; n < 4; ++n) {
            BG_PA(e, n) = 256;
            BG_PB(e, n) = 0;
            BG_PC(e, n) = 0;
            BG_PD(e, n) = 256;
            BG_X(e, n) = 0;
            BG_Y(e, n) = 0;
        }
        WIN0H(e) = WIN1H(e) = WIN0V(e) = WIN1V(e) = 0;
        WININ(e) = WINOUT(e) = 0;
        MOSAIC(e) = 0;
        BLDCNT(e) = 0;
        BLDALPHA(e) = 0;
    }
    for (int i = 0; i < 256; ++i) PAL_BG_A[i] = PAL_OBJ_A[i] = PAL_BG_B[i] = PAL_OBJ_B[i] = 0;
    for (int i = 0; i < 128; ++i) {
        OAM_A[i * 4] = OAM_B[i * 4] = 0x0200; /* hidden */
        OAM_A[i * 4 + 1] = OAM_B[i * 4 + 1] = 0;
        OAM_A[i * 4 + 2] = OAM_B[i * 4 + 2] = 0;
    }
    IPCSYNC = 0 << 8;
    DISP3DCNT = 0;
}

static void arm7_load(int on) { IPCSYNC = (u16)((on ? 1 : 0) << 8); }

/* A bright palette running through the hues. */
static void fill_palette(volatile u16* to, u32 phase) {
    for (u32 i = 1; i < 256; ++i) {
        const u32 r = (u32)((sin_q(i * 4 + phase) + 4096) >> 8) & 31, g = (u32)((sin_q(i * 4 + phase + 341) + 4096) >> 8) & 31,
                  b = (u32)((sin_q(i * 4 + phase + 682) + 4096) >> 8) & 31;
        to[i] = RGB5(r, g, b);
    }
}

/* --- 3D helpers -------------------------------------------------------------------------------------------------- */

#define TEX_SIZE(s, t) ((u32)(s) << 20 | (u32)(t) << 23)
#define TEX_FMT(f) ((u32)(f) << 26)
#define TEX_REPEAT (3u << 16)
#define TEX_FLIP (3u << 18)
#define T_COMPRESSED (0x0000u / 8 | TEX_SIZE(3, 3) | TEX_FMT(5) | TEX_REPEAT)
#define T_DIRECT (0x1000u / 8 | TEX_SIZE(3, 3) | TEX_FMT(7) | TEX_REPEAT)
#define T_A5I3 (0x3000u / 8 | TEX_SIZE(2, 2) | TEX_FMT(6) | TEX_REPEAT)
#define T_A3I5 (0x3400u / 8 | TEX_SIZE(2, 2) | TEX_FMT(1) | TEX_REPEAT)
#define T_16C (0x3800u / 8 | TEX_SIZE(3, 3) | TEX_FMT(3) | TEX_REPEAT | TEX_FLIP)
#define T_4C (0x4000u / 8 | TEX_SIZE(3, 3) | TEX_FMT(2) | TEX_REPEAT | (1u << 29))
#define T_256C (0x4800u / 8 | TEX_SIZE(3, 3) | TEX_FMT(4) | TEX_REPEAT)
#define T_POOL 0x8000u /* the churn scene's textures start here */
static const u32 TEXTURES[7] = {T_COMPRESSED, T_DIRECT, T_A5I3, T_A3I5, T_16C, T_4C, T_256C};

static u32 attr(u32 mode, u32 alpha, u32 id, u32 extra) { return 0xC0u | (mode << 4) | (alpha << 16) | (id << 24) | extra; }
#define PA_LIGHTS 15u
#define PA_XLDEPTH (1u << 11)
#define PA_FOG (1u << 15)

static void textures_write(void) {
    /* Banks A and B in LCDC here. */
    /* compressed: 256 blocks of 4 bytes, each texel picks from the block's 4 colours; slot 1 holds the block infos */
    for (int i = 0; i < 512; ++i) LCDC_A[i] = (u16)rnd();
    for (int i = 0; i < 256; ++i) LCDC_B[i] = (u16)(((u32)i * 2 & 0xFF) | 0x8000u * (i & 1) | 0x4000u * ((i >> 1) & 1));
    /* direct */
    for (int y = 0; y < 64; ++y)
        for (int x = 0; x < 64; ++x) {
            const u32 v = (u32)(sin_q((u32)x * 16) + sin_q((u32)y * 16 + (u32)x * 4) + 8192) >> 9;
            LCDC_A[0x800 + y * 64 + x] = RGB1(v & 31, (v * 2 + (u32)x) & 31, (u32)(31 - (v & 31)));
        }
    /* A5I3 and A3I5, 32 x 32: an alpha gradient and a cut-out pattern */
    for (int i = 0; i < 512; ++i) {
        const u32 x = (u32)i & 31, y = (u32)i >> 5;
        const u8 a5i3 = (u8)((x & 31) << 3 | (y & 7)), a3i5 = (u8)((((x ^ y) & 8) ? 7u : 0u) << 5 | (rnd() & 31));
        LCDC_A[0x1800 + i] = (u16)(a5i3 | (u32)a5i3 << 8);
        LCDC_A[0x1A00 + i] = (u16)(a3i5 | (u32)a3i5 << 8);
    }
    /* 16, 4 and 256 colours from noise */
    for (int i = 0; i < 1024; ++i) LCDC_A[0x1C00 + i] = (u16)rnd();
    for (int i = 0; i < 512; ++i) LCDC_A[0x2000 + i] = (u16)rnd();
    for (int i = 0; i < 2048; ++i) LCDC_A[0x2400 + i] = (u16)rnd();
    fill_palette(LCDC_E, 0);
}

static void gx_begin_scene(u32 flags) {
    VRAMCNT(BANK_A) = 0x80;
    VRAMCNT(BANK_B) = 0x80;
    VRAMCNT(BANK_E) = 0x80;
    textures_write();
    VRAMCNT(BANK_A) = 0x83;
    VRAMCNT(BANK_B) = 0x8B; /* texture slot 1 */
    VRAMCNT(BANK_E) = 0x83;
    while (GXSTAT & (1u << 27)) {
    }
    GXSTAT = 1u << 15; /* acknowledge any matrix stack error */
    DISP3DCNT = (u16)flags;
    CLEAR_COLOR = 0x3F1F0000u | RGB5(1, 2, 6);
    CLEAR_DEPTH = 0x7FFF;
    ALPHA_TEST = 8;
    FOG_COLOR = 0x1F000000u | RGB5(8, 10, 16);
    FOG_OFFSET = 0x6000;
    for (int i = 0; i < 32; ++i) REG8(0x04000360 + i) = (u8)(i * 4);
    for (int i = 0; i < 32; ++i) REG16(0x04000380 + i * 2) = RGB5(i, i, i / 2);
    for (int i = 0; i < 8; ++i) REG16(0x04000330 + i * 2) = RGB5(i * 4, 0, 31 - i * 4);
    GX(GX_VIEWPORT) = 0 | 0u << 8 | 255u << 16 | 191u << 24;
    GX(MTX_MODE) = 0;
    GX(MTX_IDENTITY) = 0;
    static const s32 P[16] = {5321, 0, 0, 0, 0, 7094, 0, 0, 0, 0, -4116, -4096, 0, 0, -821, 0};
    for (int i = 0; i < 16; ++i) GX(MTX_LOAD44) = (u32)P[i];
    GX(MTX_MODE) = 2;
    GX(MTX_IDENTITY) = 0;
    GX(GX_LIGHT_VEC) = (u32)(0x1FF & -200) | (u32)(0x1FF & -200) << 10 | (u32)(0x1FF & -300) << 20;
    GX(GX_LIGHT_COL) = 0x7FFFu;
    GX(GX_LIGHT_VEC) = 1u << 30 | (u32)(0x1FF & 300) | (u32)(0x1FF & -100) << 10 | (u32)(0x1FF & -200) << 20;
    GX(GX_LIGHT_COL) = 1u << 30 | RGB5(31, 12, 6);
    GX(GX_LIGHT_VEC) = 2u << 30 | (u32)(0x1FF & -100) | (u32)(0x1FF & 300) << 10 | (u32)(0x1FF & -200) << 20;
    GX(GX_LIGHT_COL) = 2u << 30 | RGB5(6, 12, 31);
    GX(GX_LIGHT_VEC) = 3u << 30 | (u32)(0x1FF & 100) | (u32)(0x1FF & 100) << 10 | (u32)(0x1FF & -480) << 20;
    GX(GX_LIGHT_COL) = 3u << 30 | RGB5(10, 20, 10);
    GX(GX_DIF_AMB) = RGB5(26, 26, 26) | 0x8000u | (u32)RGB5(6, 6, 6) << 16;
    GX(GX_SPE_EMI) = RGB5(12, 12, 12) | 0x8000u | (u32)RGB5(0, 0, 2) << 16;
}

static void gx_rotate(u32 ax, u32 ay, s32 z) {
    GX(MTX_MODE) = 2;
    GX(MTX_IDENTITY) = 0;
    GX(MTX_TRANS) = 0;
    GX(MTX_TRANS) = 0;
    GX(MTX_TRANS) = (u32)z;
    const s32 cx = cos_q(ax), sx = sin_q(ax), cy = cos_q(ay), sy = sin_q(ay);
    const s32 m[9] = {cy, 0, -sy, (sx * sy) >> 12, cx, (sx * cy) >> 12, (cx * sy) >> 12, -sx, (cx * cy) >> 12};
    for (int i = 0; i < 9; ++i) GX(MTX_MULT33) = (u32)m[i];
}

static inline void gx_vertex(s32 x, s32 y, s32 z) {
    GX(GX_VTX16) = (u32)(x & 0xFFFF) | (u32)y << 16;
    GX(GX_VTX16) = (u32)(z & 0xFFFF);
}

/* A display list in RAM, sent by GX FIFO DMA the way games do: a torus of packed vertex commands. */
#define LIST ((u32*)0x02280000)
static u32 list_words;

static u32 pack_normal(s32 x, s32 y, s32 z) {
    return (u32)((x >> 3) & 0x3FF) | (u32)((y >> 3) & 0x3FF) << 10 | (u32)((z >> 3) & 0x3FF) << 20;
}

static void build_torus(int columns, int rows) {
    u32* l = LIST;
    const s32 R = 5200, r = 2200;
    for (int v = 0; v < rows; ++v) {
        *l++ = GX_BEGIN;
        *l++ = TRI_STRIP;
        for (int u = 0; u <= columns; ++u)
            for (int side = 0; side < 2; ++side) {
                const u32 au = (u32)u * 1024u / (u32)columns, av = (u32)(v + side) * 1024u / (u32)rows;
                const s32 cu = cos_q(au), su = sin_q(au), cv = cos_q(av), sv = sin_q(av);
                const s32 x = ((R + ((r * cv) >> 12)) * cu) >> 12, y = (r * sv) >> 12, z = ((R + ((r * cv) >> 12)) * su) >> 12;
                *l++ = (u32)GX_NORMAL | (u32)GX_TEXCOORD << 8 | (u32)GX_VTX16 << 16;
                *l++ = pack_normal((cv * cu) >> 12, sv, (cv * su) >> 12);
                *l++ = (u32)((u * 32) & 0xFFFF) | (u32)((v + side) * 32) << 16;
                *l++ = (u32)(x & 0xFFFF) | (u32)y << 16;
                *l++ = (u32)(z & 0xFFFF);
            }
        *l++ = GX_END;
    }
    list_words = (u32)(l - LIST);
}

static void send_list(void) {
    while (DMA_CTL(0) & DMA_ON) {
    }
    DMA_SRC(0) = (u32)LIST;
    DMA_DST(0) = 0x04000400;
    DMA_CTL(0) = DMA_ON | DMA_32 | DMA_GX | DMA_DST_FIX | list_words;
}

static void draw_torus(u32 n, u32 turn, s32 z, u32 tex) {
    gx_rotate(n * 3 + turn, n * 5 + turn * 3, z);
    GX(GX_POLY_ATTR) = attr(0, 31, 1, PA_LIGHTS);
    GX(GX_TEX_PARAM) = tex;
    GX(GX_PAL_BASE) = 0;
    send_list();
}

/* --- 2D storm: both engines at their busiest. ---------------------------------------------------------------------*/

static u32 hdma_table[2][192];
static u16 oam_shadow[2][512];

/* Tiles, maps, an affine bitmap and sprites into a BG region of at least 64 KB and an OBJ region of at least 16 KB. */
static void storm_vram(volatile u16* bg, volatile u16* obj, volatile u16* pal_bg, volatile u16* pal_obj, u32 phase) {
    fill_palette(pal_bg, phase);
    fill_palette(pal_obj, phase + 200);
    for (int i = 0; i < 1024; ++i) {
        bg[i] = (u16)(rnd() & 63);        /* BG0/1 maps at 0x0000 and 0x0800 */
        bg[0x400 + i] = (u16)(rnd() & 63);
    }
    for (int i = 0; i < 0x2000; ++i) {    /* 128 x 128 bitmaps at 0x4000 and 0x8000 */
        const u32 x = (u32)i & 127, y = (u32)i >> 7;
        bg[0x2000 + i] = (u16)(((x ^ y) * 2 + phase) | ((x * y >> 4) & 255) << 8);
        bg[0x4000 + i] = (u16)((x * x + y * y) >> 4 | (rnd() & 0xFF00));
    }
    for (int i = 0; i < 0x2000; ++i) bg[0x6000 + i] = (u16)rnd(); /* 8bpp tiles at 0xC000 */
    for (int i = 0; i < 0x1000; ++i) {
        const u32 x = (u32)i & 31, y = ((u32)i >> 4) & 31;
        const u32 d = (x - 16) * (x - 16) + (y - 16) * (y - 16);
        obj[i] = d < 200 ? (u16)((d + 1) | (d + 2) << 8) : 0;
    }
}

static void storm_regs(int e, int with_3d) {
    u32 dispcnt = 5u | 1u << 16 | 1u << 4 | 1u << 12 | 0xFu << 8 | 1u << 13 | 1u << 14;
    if (with_3d) dispcnt |= 1u << 3;
    if (e) DISPCNT_B = dispcnt;
    else DISPCNT_A = dispcnt;
    if (!with_3d) BG_CNT(e, 0) = (u16)(1u << 7 | 3u << 2 | 0u << 8 | 3u);
    BG_CNT(e, 1) = (u16)(1u << 7 | 3u << 2 | 1u << 8 | 2u);
    BG_CNT(e, 2) = (u16)(1u << 7 | 8u << 8 | 1u << 13 | 1u);
    BG_CNT(e, 3) = (u16)(1u << 7 | 16u << 8 | 1u << 13 | 0u);
    BLDCNT(e) = (u16)(2u | 16u | 1u << 6 | 12u << 8 | 32u << 8);
    BLDALPHA(e) = 10 | 8u << 8;
    WININ(e) = 0x1F | 0x1Du << 8;
    WINOUT(e) = 0x3F;
}

static void storm_frame(int e, u32 n, volatile u16* oam) {
    /* per-line scroll by HBlank DMA, re-armed each frame */
    const int ch = 1 + e;
    u32* table = hdma_table[e];
    for (int y = 0; y < 192; ++y) table[y] = (u32)(sin_q((u32)y * 8 + n * 6) >> 7 & 0x1FF) | (u32)(n & 0x1FF) << 16;
    DMA_CTL(ch) = 0;
    DMA_SRC(ch) = (u32)table;
    DMA_DST(ch) = 0x04000014 + (u32)e * 0x1000;
    DMA_CTL(ch) = DMA_ON | DMA_32 | DMA_REPEAT | DMA_HBLANK | DMA_DST_RELOAD | 1;
    /* affine BGs turning */
    for (int b = 2; b < 4; ++b) {
        const u32 a = n * (u32)(b + e + 1);
        const s32 c = cos_q(a) >> 4, s = sin_q(a) >> 4;
        BG_PA(e, b) = (u16)c;
        BG_PB(e, b) = (u16)(-s);
        BG_PC(e, b) = (u16)s;
        BG_PD(e, b) = (u16)c;
        BG_X(e, b) = (u32)(sin_q(n * 2) * 8);
        BG_Y(e, b) = (u32)(cos_q(n * 3) * 8);
    }
    WIN0H(e) = (u16)(((n * 2) & 127) << 8 | (((n * 2) & 127) + 120));
    WIN0V(e) = (u16)((sin_q(n * 4) >> 7) + 40) << 8 | (u16)((sin_q(n * 4) >> 7) + 150);
    /* 128 double-size rotated, blended sprites */
    u16* shadow = oam_shadow[e];
    for (u32 i = 0; i < 128; ++i) {
        const u32 a = n * 3 + i * 40;
        const u32 x = (u32)((sin_q(a) * 110) >> 12) + 96, y = (u32)((cos_q(a + i * 8) * 70) >> 12) + 64;
        shadow[i * 4] = (u16)((y & 0xFF) | 1u << 8 | 1u << 9 | 1u << 10 | 1u << 13);
        shadow[i * 4 + 1] = (u16)((x & 0x1FF) | (i & 31) << 9 | 2u << 14);
        shadow[i * 4 + 2] = 0;
    }
    for (u32 g = 0; g < 32; ++g) {
        const u32 a = n * 4 + g * 32;
        const s32 c = cos_q(a) >> 4, s = sin_q(a) >> 4;
        shadow[g * 16 + 3] = (u16)c;
        shadow[g * 16 + 7] = (u16)(-s);
        shadow[g * 16 + 11] = (u16)s;
        shadow[g * 16 + 15] = (u16)c;
    }
    DMA_SRC(3) = (u32)shadow;
    DMA_DST(3) = (u32)oam;
    DMA_CTL(3) = DMA_ON | DMA_32 | 256;
    while (DMA_CTL(3) & DMA_ON) {
    }
}

volatile u32 g_vblanks;

void irq_handler(void) {
    const u32 pending = IE & IF;
    IF = pending;
    if (pending & 1) ++g_vblanks;
    if (pending & 2) {
        /* a copper bar on the backdrop, as many games do on an HBlank interrupt */
        const u32 line = VCOUNT;
        PAL_BG_B[0] = (u16)(line & 31);
    }
}

static void hblank_irq(void) {
    DISPSTAT = (u16)(DISPSTAT | 1u << 4);
    IE = 2;
    IME = 1;
    irq_on();
}

/* --- Scenes ------------------------------------------------------------------------------------------------------ */

/* PACE: almost no work; the display path alone. A band sweeping 4 px per frame on both panels and a ruler sprite that
 * moves one cell a frame, so a dropped frame shows on camera as well as in the numbers. */
static void bitmap_screens(void) {
    VRAMCNT(BANK_A) = 0x81;
    VRAMCNT(BANK_C) = 0x84;
    VRAMCNT(BANK_B) = 0x82;
    VRAMCNT(BANK_D) = 0x84;
    DISPCNT_A = 5u | 1u << 16 | 1u << 11 | 1u << 12 | 1u << 4;
    DISPCNT_B = 5u | 1u << 16 | 1u << 11 | 1u << 12 | 1u << 4;
    BG_CNT(0, 3) = (u16)(1u << 14 | 1u << 7 | 1u << 2 | 1u << 13);
    BG_CNT(1, 3) = (u16)(1u << 14 | 1u << 7 | 1u << 2 | 1u << 13);
}

static void pace_init(void) {
    bitmap_screens();
    for (int y = 0; y < 256; ++y)
        for (int x = 0; x < 256; ++x) {
            const u32 band = (u32)x < 32 ? 31 : (u32)x < 40 ? 0 : (u32)((x >> 4) & 1) * 4 + 4;
            const u16 c = RGB1(band, band, band);
            BG_A[y * 256 + x] = c;
            BG_B[y * 256 + x] = c;
        }
    for (int i = 0; i < 16; ++i) OBJ_A[i] = OBJ_B[i] = 0x1111;
    PAL_OBJ_A[1] = PAL_OBJ_B[1] = RGB5(31, 8, 0);
}

static void pace_frame(u32 n) {
    BG_X(0, 3) = (n * 4) << 8;
    BG_X(1, 3) = (n * 4) << 8;
    const u32 cell = n % 60;
    OAM_A[0] = OAM_B[0] = (u16)(92 + cell / 12 * 10);
    OAM_A[1] = OAM_B[1] = (u16)((cell % 12) * 20 + 8);
}

/* SHOWCASE: flat-coloured art with every kind of edge, scrolling on both screens, and next to no other work. What is left
 * of the frame's cost is the filter or shader the test is about. */
static void showcase_init(void) {
    static const u16 INKS[8] = {RGB1(31, 31, 28), RGB1(4, 6, 14), RGB1(30, 8, 6), RGB1(6, 22, 10),
                                RGB1(28, 24, 4),  RGB1(6, 14, 28), RGB1(24, 10, 26), RGB1(16, 16, 18)};
    bitmap_screens();
    for (int y = 0; y < 256; ++y)
        for (int x = 0; x < 256; ++x) {
            const int cx = x >> 5, cy = y >> 5, u = x & 31, v = y & 31, kind = (cx * 3 + cy * 5) & 3;
            int on;
            if (kind == 0) on = (u - 16) * (u - 16) + (v - 16) * (v - 16) < 144;
            else if (kind == 1) on = ((u + v) >> 2) & 1;
            else if (kind == 2) on = v > u * 2 - 8 && v < u * 2 + 8;
            else on = ((u ^ v) >> 1) & 1;
            const u16 ink = INKS[(cx + cy * 3) & 7], paper = INKS[(cx * 5 + cy + 3) & 7];
            BG_A[y * 256 + x] = on ? ink : paper;
            BG_B[((y + 64) & 255) * 256 + x] = on ? paper : ink;
        }
}

static void showcase_frame(u32 n) {
    BG_X(0, 3) = n << 8;
    BG_Y(0, 3) = (n / 2) << 8;
    BG_X(1, 3) = (0u - n) << 8;
    BG_Y(1, 3) = (n / 2) << 8;
}

static void plain_init(void) {
    bitmap_screens();
    for (int i = 0; i < 0x10000; ++i) {
        const u16 c = RGB1((u32)(i & 255) >> 4, (u32)(i >> 8) >> 4, 4);
        BG_A[i] = c;
        BG_B[i] = c;
    }
}

/* ARM9: the CPU alone, saturated, every result checked. */
static void cpu_frame(u32 n) {
    BG_Y(0, 3) = (n * 2) << 8;
    BG_Y(1, 3) = (n * 3) << 8;
    burn_until(BURN_LINE);
}

/* JIT: code rewritten every frame and run, as overlays and self-modifying games force on a recompiler. */
#define CODE ((u32*)0x02200000)
static void jit_frame(u32 n) {
    typedef u32 (*Fn)(u32);
    BG_Y(0, 3) = (n * 2) << 8;
    BG_Y(1, 3) = (n * 3) << 8;
    for (u32 f = 0; f < 24; ++f) {
        u32* code = CODE + f * 256;
        u32 expect = n + f, x = 0x9E3779B9u * (n * 32 + f);
        for (u32 i = 0; i < 255; ++i) {
            x ^= x << 13;
            x ^= x >> 17;
            x ^= x << 5;
            const u32 imm = x & 255;
            if (x & 256) {
                code[i] = 0xE2800000u | imm; /* add r0, r0, #imm */
                expect += imm;
            } else {
                code[i] = 0xE2200000u | imm; /* eor r0, r0, #imm */
                expect ^= imm;
            }
        }
        code[255] = 0xE12FFF1Eu; /* bx lr */
        cp15_flush_code();
        const u32 got = ((Fn)(void*)code)(n + f);
        if (got != expect) ++g_wrong;
    }
    burn_until(BURN_LINE);
}

/* ARM7: all 16 sound channels plus a busy ARM7, against a busy ARM9. */
static void arm7_init(void) {
    plain_init();
    volatile s16* samples = (volatile s16*)0x02300000;
    for (int ch = 0; ch < 8; ++ch)
        for (int i = 0; i < 0x800; ++i) samples[ch * 0x800 + i] = (s16)(sin_q((u32)i * (u32)(ch + 2) * 4) * 4);
    arm7_load(1);
}

/* 2D: both engines, all layers, 128 rotated sprites, per-line scroll, windows, blending, an HBlank interrupt. */
static void storm_init(void) {
    VRAMCNT(BANK_A) = 0x81;
    VRAMCNT(BANK_B) = 0x82;
    VRAMCNT(BANK_C) = 0x84;
    VRAMCNT(BANK_D) = 0x84;
    storm_vram(BG_A, OBJ_A, PAL_BG_A, PAL_OBJ_A, 0);
    storm_vram(BG_B, OBJ_B, PAL_BG_B, PAL_OBJ_B, 300);
    storm_regs(0, 0);
    storm_regs(1, 0);
    hblank_irq();
}

static void storm_scene(u32 n) {
    storm_frame(0, n, OAM_A);
    storm_frame(1, n, OAM_B);
    fill_palette(PAL_BG_A, n * 2);
    burn_until(170);
}

/* GEOMETRY: the hardware's whole polygon budget, textured and lit by four lights, through FIFO DMA, on one screen. */
static void geometry_init(void) {
    plain_init();
    VRAMCNT(BANK_A) = 0;
    VRAMCNT(BANK_B) = 0;
    gx_begin_scene(1u | 1u << 3 | 1u << 4 | 1u << 5);
    DISPCNT_A = 1u << 16 | 1u << 3 | 1u << 8;
    BG_CNT(0, 0) = 0;
    build_torus(31, 31);
}

static void geometry_frame(u32 n) {
    BG_Y(1, 3) = (n * 2) << 8;
    draw_torus(n, 0, -14000, T_DIRECT);
    burn_until(120);
    while (DMA_CTL(0) & DMA_ON) burn_batch();
    GX(GX_SWAP) = 0;
    burn_until(BURN_LINE);
}

/* FILL: layers of full-screen translucent, fogged polygons with edge marking, anti-aliasing and a shadow volume. The
 * cost is pixels: this is what grows with the resolution. */
#define FILL_LAYERS 12
static void fill_init(void) {
    plain_init();
    VRAMCNT(BANK_A) = 0;
    VRAMCNT(BANK_B) = 0;
    gx_begin_scene(1u | 1u << 2 | 1u << 3 | 1u << 4 | 1u << 5 | 1u << 7 | 4u << 8);
    DISPCNT_A = 1u << 16 | 1u << 3 | 1u << 8;
}

static void screen_quad(s32 z, u32 n, s32 size) {
    GX(GX_BEGIN) = QUADS;
    const u32 s = n * 16, t = n * 8;
    GX(GX_TEXCOORD) = (s & 0xFFFF) | t << 16;
    gx_vertex(-size, -size, z);
    GX(GX_TEXCOORD) = ((s + 4096) & 0xFFFF) | t << 16;
    gx_vertex(size, -size, z);
    GX(GX_TEXCOORD) = ((s + 4096) & 0xFFFF) | (t + 4096) << 16;
    gx_vertex(size, size, z);
    GX(GX_TEXCOORD) = (s & 0xFFFF) | (t + 4096) << 16;
    gx_vertex(-size, size, z);
    GX(GX_END) = 0;
}

static void fill_frame(u32 n) {
    BG_Y(1, 3) = (n * 2) << 8;
    gx_rotate(0, 0, -8192);
    /* an opaque back wall, then the translucent layers far to near */
    GX(GX_POLY_ATTR) = attr(0, 31, 1, 0);
    GX(GX_TEX_PARAM) = T_DIRECT;
    GX(GX_COLOR) = 0x7FFF;
    screen_quad(-4000, n, 16000);
    GX(GX_PAL_BASE) = 0;
    for (u32 i = 0; i < FILL_LAYERS; ++i) {
        GX(GX_POLY_ATTR) = attr(0, 10 + i, 2 + i, PA_FOG);
        GX(GX_TEX_PARAM) = TEXTURES[i % 7];
        GX(GX_COLOR) = RGB5(31 - i, 16 + i, 10 + i);
        screen_quad(-3000 + (s32)i * 400, n + i * 16, 16000);
    }
    /* a shadow volume across the middle */
    GX(GX_TEX_PARAM) = 0;
    GX(GX_POLY_ATTR) = attr(3, 20, 0, 0);
    screen_quad(3000, 0, 4000);
    GX(GX_POLY_ATTR) = attr(3, 20, 63, 0);
    screen_quad(3000, 0, 4000);
    GX(GX_SWAP) = 0;
    burn_until(BURN_LINE);
}

/* CHURN: textures and palettes rewritten every frame, the renderer's texture cache never gets to rest. */
#define CHURN_COUNT 48
#define CHURN_POOL ((u16*)0x02240000)
static void churn_init(void) {
    plain_init();
    VRAMCNT(BANK_A) = 0;
    VRAMCNT(BANK_B) = 0;
    gx_begin_scene(1u | 1u << 3);
    DISPCNT_A = 1u << 16 | 1u << 3 | 1u << 8;
    for (int i = 0; i < 0x10000; ++i) CHURN_POOL[i] = (u16)rnd() | 0x8000;
}

static void churn_frame(u32 n) {
    BG_Y(1, 3) = (n * 2) << 8;
    /* Two banks take turns as the texture slot, the way a game streams them: the 3D render of the coming frame starts
     * long before VBlank ends, so the upload goes to the bank it is not reading, and the swap is the next VBlank. */
    const u32 odd = n & 1;
    VRAMCNT(BANK_A) = odd ? 0x83 : 0x80;
    VRAMCNT(BANK_B) = odd ? 0x80 : 0x83;
    VRAMCNT(BANK_E) = 0x80;
    /* 48 direct-colour 32 x 32 textures: 96 KB a frame */
    DMA_SRC(3) = (u32)(CHURN_POOL + (n * 397 & 0x3FFF));
    DMA_DST(3) = (u32)(odd ? LCDC_B : LCDC_A) + T_POOL;
    DMA_CTL(3) = DMA_ON | DMA_32 | (CHURN_COUNT * 512);
    while (DMA_CTL(3) & DMA_ON) {
    }
    fill_palette(LCDC_E, n * 4);
    VRAMCNT(BANK_E) = 0x83;
    gx_rotate(0, 0, -8192);
    GX(GX_COLOR) = 0x7FFF;
    GX(GX_POLY_ATTR) = attr(0, 31, 1, 0);
    for (u32 i = 0; i < CHURN_COUNT; ++i) {
        GX(GX_TEX_PARAM) = (T_POOL + i * 2048) / 8 | TEX_SIZE(2, 2) | TEX_FMT(7);
        const s32 x = -6000 + (s32)(i % 8) * 1600, y = -4400 + (s32)(i / 8) * 1600;
        GX(GX_BEGIN) = QUADS;
        GX(GX_TEXCOORD) = 0;
        gx_vertex(x, y, -2000);
        GX(GX_TEXCOORD) = 32u * 16;
        gx_vertex(x + 1500, y, -2000);
        GX(GX_TEXCOORD) = 32u * 16 | (32u * 16) << 16;
        gx_vertex(x + 1500, y + 1500, -2000);
        GX(GX_TEXCOORD) = (32u * 16) << 16;
        gx_vertex(x, y + 1500, -2000);
        GX(GX_END) = 0;
    }
    GX(GX_SWAP) = 0;
    burn_until(BURN_LINE);
}

/* SPIKE: a state not seen before every 20 frames, in a scene that is otherwise light. A renderer that builds pipelines
 * or shaders on first use stalls right here; only the worst frames matter, and they count a lot. */
static void spike_init(void) {
    plain_init();
    VRAMCNT(BANK_A) = 0;
    VRAMCNT(BANK_B) = 0;
    gx_begin_scene(1u | 1u << 2 | 1u << 3);
    DISPCNT_A = 1u << 16 | 1u << 3 | 1u << 8;
}

static void spike_frame(u32 n) {
    BG_Y(1, 3) = (n * 2) << 8;
    const u32 state = n / 20;
    DISP3DCNT = (u16)(1u | (state & 1) << 1 | 1u << 3 | ((state >> 1) & 1) << 2 | ((state >> 2) & 1) << 4 | ((state >> 3) & 1) << 5 |
                      ((state >> 4) & 1) << 7 | 4u << 8);
    gx_rotate(0, 0, -8192);
    for (u32 i = 0; i < 24; ++i) {
        const u32 s = state * 3 + i * 5;
        const u32 mode = s % 3, alpha = (s >> 2) & 1 ? 31 : 8 + ((s >> 3) & 15), fog = (s >> 7) & 1 ? PA_FOG : 0;
        GX(GX_POLY_ATTR) = attr(mode, alpha, i + 1, fog | ((s >> 8) & 1 ? PA_XLDEPTH : 0));
        GX(GX_TEX_PARAM) = TEXTURES[s % 7];
        GX(GX_COLOR) = RGB5(s & 31, (s >> 2) & 31, 31 - (s & 31));
        const s32 x = -6000 + (s32)(i % 6) * 2000, y = -4400 + (s32)(i / 6) * 2200;
        GX(GX_BEGIN) = TRIS;
        GX(GX_TEXCOORD) = 0;
        gx_vertex(x, y, -2000 + (s32)i * 16);
        GX(GX_TEXCOORD) = 512;
        gx_vertex(x + 1900, y, -2000 + (s32)i * 16);
        GX(GX_TEXCOORD) = 512u << 16;
        gx_vertex(x, y + 2100, -2000 + (s32)i * 16);
        GX(GX_END) = 0;
    }
    GX(GX_SWAP) = 0;
    burn_until(100);
}

/* DUAL: 3D on both screens the way games do it, a frame each in turn, the other held through a display capture. */
static void dual_init(void) {
    gx_begin_scene(1u | 1u << 3 | 1u << 4);
    VRAMCNT(BANK_C) = 0x80;
    VRAMCNT(BANK_D) = 0x84; /* sub OBJ */
    DISPCNT_A = 1u << 16 | 1u << 3 | 1u << 8;
    /* The sub engine shows the capture from C as a bitmap BG, or from D as a grid of bitmap sprites: only one of the two
     * is mapped at a time, and the other reads as transparent. */
    DISPCNT_B = 5u | 1u << 16 | 1u << 11 | 1u << 12 | 1u << 5;
    BG_CNT(1, 3) = (u16)(1u << 14 | 1u << 7 | 1u << 2);
    for (u32 y = 0; y < 3; ++y)
        for (u32 x = 0; x < 4; ++x) {
            const u32 i = y * 4 + x;
            OAM_B[i * 4] = (u16)(y * 64 | 3u << 10);
            OAM_B[i * 4 + 1] = (u16)(x * 64 | 3u << 14);
            OAM_B[i * 4 + 2] = (u16)(x * 8 | (y * 8) << 5 | 15u << 12);
        }
    build_torus(23, 17);
}

static void dual_frame(u32 n) {
    const u32 odd = n & 1;
    /* odd: main on top, capture into D for the bottom's next hold; even: the other way round */
    POWCNT1 = (u16)(odd ? 0x820F : 0x020F);
    VRAMCNT(BANK_C) = odd ? 0x84 : 0x80;
    VRAMCNT(BANK_D) = odd ? 0x80 : 0x84;
    DISPCAPCNT = 1u << 31 | 3u << 20 | (odd ? 3u : 2u) << 16 | 16u | 0u << 8;
    draw_torus(n, odd * 256, -14000, TEXTURES[odd * 4 + 1]);
    burn_until(120);
    while (DMA_CTL(0) & DMA_ON) burn_batch();
    GX(GX_SWAP) = 0;
    burn_until(BURN_LINE);
}

/* FEEDBACK: last frame's capture read back as this frame's texture: the slowest path a high-resolution renderer has. */
static void feedback_init(void) {
    gx_begin_scene(1u | 1u << 3);
    DISPCNT_A = 1u << 16 | 1u << 3 | 1u << 8;
    DISPCNT_B = 1u << 16; /* C and D are busy here: the sub screen is its backdrop, a new colour each frame */
    build_torus(15, 11);
}

static void feedback_frame(u32 n) {
    const u32 odd = n & 1;
    PAL_BG_B[0] = (u16)(n * 33);
    /* bank C and D take turns: one captured into (LCDC), the other a texture slot */
    VRAMCNT(BANK_C) = odd ? 0x80 : 0x93; /* slot 2 */
    VRAMCNT(BANK_D) = odd ? 0x9B : 0x80; /* slot 3 */
    DISPCAPCNT = 1u << 31 | 3u << 20 | (odd ? 2u : 3u) << 16 | 16u;
    gx_rotate(0, 0, -8192);
    GX(GX_POLY_ATTR) = attr(0, 31, 1, 0);
    /* drawn in the next frame, from the bank being captured into now */
    GX(GX_TEX_PARAM) = (odd ? 0x40000u : 0x60000u) / 8 | TEX_SIZE(5, 5) | TEX_FMT(7);
    GX(GX_COLOR) = RGB5(30, 30, 30);
    GX(GX_BEGIN) = QUADS;
    GX(GX_TEXCOORD) = 0;
    gx_vertex(-5600, -4200, -2000);
    GX(GX_TEXCOORD) = 256u * 16;
    gx_vertex(5600, -4200, -2000);
    GX(GX_TEXCOORD) = 256u * 16 | (192u * 16) << 16;
    gx_vertex(5600, 4200, -2000);
    GX(GX_TEXCOORD) = (192u * 16) << 16;
    gx_vertex(-5600, 4200, -2000);
    GX(GX_END) = 0;
    draw_torus(n, 0, -16000, T_16C);
    burn_until(120);
    while (DMA_CTL(0) & DMA_ON) burn_batch();
    GX(GX_SWAP) = 0;
    burn_until(BURN_LINE);
}

/* GAUNTLET: all of it at once. A game at its very worst: 3D with translucent layers and a capture on the main engine,
 * sprites and per-line effects on both, the ARM9 busy to the last line, the ARM7 mixing every channel. */
static void gauntlet_init(void) {
    arm7_init();
    VRAMCNT(BANK_A) = 0;
    VRAMCNT(BANK_B) = 0;
    gx_begin_scene(1u | 1u << 2 | 1u << 3 | 1u << 4 | 1u << 7 | 4u << 8);
    VRAMCNT(BANK_F) = 0x81; /* main BG 0x06000000: 16 KB of it for the maps */
    VRAMCNT(BANK_G) = 0x82; /* main OBJ */
    VRAMCNT(BANK_D) = 0x80; /* capture target */
    VRAMCNT(BANK_C) = 0x84;
    VRAMCNT(BANK_I) = 0x82; /* sub OBJ */
    for (int i = 0; i < 1024; ++i) ((volatile u16*)0x06000000)[i] = (u16)(rnd() & 63);
    fill_palette(PAL_BG_A, 0);
    fill_palette(PAL_OBJ_A, 200);
    for (int i = 0; i < 0x1000; ++i) {
        const u32 x = (u32)i & 31, y = ((u32)i >> 4) & 31;
        const u32 d = (x - 16) * (x - 16) + (y - 16) * (y - 16);
        OBJ_A[i] = d < 200 ? (u16)((d + 1) | (d + 2) << 8) : 0;
    }
    volatile u16* sub_obj = (volatile u16*)0x06600000;
    for (int i = 0; i < 0x1000; ++i) sub_obj[i] = OBJ_A[i];
    storm_vram(BG_B, sub_obj, PAL_BG_B, PAL_OBJ_B, 300);
    storm_regs(0, 1);
    storm_regs(1, 0);
    DISPCNT_A = 1u << 16 | 1u << 3 | 1u << 8 | 1u << 12 | 1u << 4;
    build_torus(23, 17);
    hblank_irq();
}

static void gauntlet_frame(u32 n) {
    DISPCAPCNT = 1u << 31 | 3u << 20 | 3u << 16 | 16u;
    storm_frame(0, n, OAM_A);
    storm_frame(1, n, OAM_B);
    draw_torus(n, 0, -14000, T_DIRECT);
    while (DMA_CTL(0) & DMA_ON) burn_batch();
    /* translucent cards over it */
    gx_rotate(0, n * 2, -8192);
    GX(GX_PAL_BASE) = 0;
    for (u32 i = 0; i < 6; ++i) {
        GX(GX_POLY_ATTR) = attr(0, 12 + i, 2 + i, PA_FOG);
        GX(GX_TEX_PARAM) = TEXTURES[(i + 2) % 7];
        GX(GX_COLOR) = RGB5(31, 20 + i, 16 + i);
        screen_quad(-1000 + (s32)i * 500, n + i * 32, 12000);
    }
    GX(GX_SWAP) = 0;
    burn_until(BURN_LINE);
}

const Scene SCENES[SCENE_COUNT] = {
    [SC_PACE] = {pace_init, pace_frame},        [SC_ARM9] = {plain_init, cpu_frame},
    [SC_JIT] = {plain_init, jit_frame},         [SC_ARM7] = {arm7_init, cpu_frame},
    [SC_STORM] = {storm_init, storm_scene},     [SC_GEOMETRY] = {geometry_init, geometry_frame},
    [SC_FILL] = {fill_init, fill_frame},        [SC_CHURN] = {churn_init, churn_frame},
    [SC_SPIKE] = {spike_init, spike_frame},     [SC_DUAL] = {dual_init, dual_frame},
    [SC_FEEDBACK] = {feedback_init, feedback_frame}, [SC_GAUNTLET] = {gauntlet_init, gauntlet_frame},
    [SC_SHOWCASE] = {showcase_init, showcase_frame},
};
